int[] notas = {7, 9, 5};

for (int i = 0; i < notas.length; i++) {
  System.out.println(notas[i]);
}

// i <= notas.length quebraria na ultima volta

int[] notas = {7, 9, 5};

for (int nota : notas) {
  System.out.println(nota);
}

int[] notas = {7, 9, 5};
int total = 0;

for (int nota : notas) {
  total += nota;
}

System.out.println(total);              // 21
System.out.println((double) total / notas.length);  // 7.0

